with open('baseline_extract.json', 'r', encoding='utf-8') as f:
    baseline = json.load(f)
baseline_by_fn = {b['filename']: b for b in baseline}

for entry in entries:
    fn = entry['filename']
    if fn in baseline_by_fn:
        b = baseline_by_fn[fn]
        entry['filepath'] = b['filepath']; entry['page_count'] = b.get('page_count', 0)
        entry['is_scanned'] = b.get('is_scanned'); entry['has_bookmarks'] = b.get('has_bookmarks')
        bm = b.get('bookmark_titles')
        entry['bookmark_titles'] = [item['title'] for item in bm if isinstance(item, dict)] if bm and isinstance(bm, list) else []

with open('bookdata.json', 'r', encoding='utf-8') as f: existing = json.load(f)
existing_fns = {b['filename'] for b in existing}; added = 0
for entry in entries:
    if entry['filename'] not in existing_fns: existing.append(entry); existing_fns.add(entry['filename']); added += 1
with open('bookdata.json', 'w', encoding='utf-8') as f: json.dump(existing, f, ensure_ascii=False, indent=2)

